// ---- host logic: examples/api_tours/extension_3d/host.cpp ----
// API tour (C++ Wrapper): dynamic extensions and a host-driven 3D scene. Same page, checks and case
// as examples/c/ports/kui_api_extension_3d.c (and the Go / Rust ports): the host builds a scene in
// <kui-3d-view> through ExtensionManager::invoke (meshes, lights, materials, a glTF model, an orbit
// camera driven by mouse events), inspects the kui_ext_3d extension (state, perf stats, watch),
// unloads and reloads it and rebuilds the scene, and reads every invoke result. One #tour-log row
// per check; #tour-result ends as "PASS n/n (known bugs: k)". The panel buttons repeat the calls.
//
// Document::dispatchMouse (kui_devtools_dispatch_mouse_event) injects the mouse drags and the wheel
// step that drive the orbit camera through the same dispatch path as real input.
// Wrapper shapes that differ from the C port (checked through the closest public method):
//   * ExtensionManager::invoke returns the whole result (status, values, error) at once; the C
//     result object (kui_extension_result_*) is read and released inside it.
//   * The manager state is two calls (count(), isWatching()); unloadExtension returns false where
//     the C call returns KUI_ERR_NOT_FOUND; load / reload return the C out flag.
//   * The model path is built from tour_executable_dir(): the C++ tour loads its page from a
//     string, so the page has no file location to resolve relative paths against.

#include <cmath>
#include <cstdint>
#include <cstdio>
#include <functional>
#include <sstream>
#include <vector>

namespace {

#ifdef _WIN32
const char* const k_ext_file = "kui_ext_3d.dll";
#elif defined(__APPLE__)
const char* const k_ext_file = "libkui_ext_3d.dylib";
#else
const char* const k_ext_file = "libkui_ext_3d.so";
#endif

const char* const k_tag = "kui-3d-view";

kui::Document* g_doc = nullptr;

// ---- Self-check bookkeeping: count, log one <tr> per check, publish the verdict ----------
// check():  a documented behaviour; a failure makes the tour FAIL.
// known():  a documented behaviour the engine currently gets wrong (reported bug). A failure is
//           logged as "KNOWN BUG" and kept out of the verdict; once it passes it counts as ok.

int g_total = 0;
int g_failed = 0;
int g_known = 0;
std::string g_failed_names;

template <typename... Parts>
std::string cat(const Parts&... parts) {
    std::ostringstream out;
    out.setf(std::ios::fixed);
    out.precision(2);
    (out << ... << parts);
    return out.str();
}

std::string fixed(double value, int digits) {
    char buf[48];
    std::snprintf(buf, sizeof buf, "%.*f", digits, value);
    return buf;
}

void log_row(const std::string& name, const std::string& result, const std::string& cell) {
    kui::Element* log = g_doc->getElementById("tour-log");
    if (!log) return;
    auto row = g_doc->createElement("tr");
    row->setAttribute("data-check", name);
    row->setAttribute("data-result", result);
    if (result != "ok") row->addClass("bad");
    auto first = g_doc->createElement("td");
    first->setTextContent(name);
    row->appendChild(first);
    auto second = g_doc->createElement("td");
    second->setTextContent(cell);
    row->appendChild(second);
    log->appendChild(row);
}

void check(const std::string& name, bool ok, const std::string& detail) {
    g_total++;
    if (ok) {
        log_row(name, "ok", "ok");
        return;
    }
    g_failed++;
    g_failed_names += (g_failed_names.empty() ? "" : ", ") + name;
    std::fprintf(stderr, "tour check failed: %s: %s\n", name.c_str(), detail.c_str());
    log_row(name, "fail", "FAIL: " + detail);
}

void known(const std::string& name, bool ok, const std::string& bug, const std::string& detail) {
    if (ok) {
        g_total++;
        log_row(name, "ok", "ok");
        return;
    }
    g_known++;
    std::fprintf(stderr, "tour known bug: %s: %s\n", name.c_str(), detail.c_str());
    log_row(name, "known", "KNOWN BUG: " + bug + " (" + detail + ")");
}

void finish() {
    kui::Element* result = g_doc->getElementById("tour-result");
    if (!result) return;
    std::string text = g_failed == 0 ? cat("PASS ", g_total, "/", g_total)
                                     : cat("FAIL ", g_failed, "/", g_total, ": ", g_failed_names);
    if (g_known) text += cat(" (known bugs: ", g_known, ")");
    result->setTextContent(text);
    result->setAttribute("data-total", std::to_string(g_total));
    result->setAttribute("data-failed", std::to_string(g_failed));
    result->setAttribute("data-known", std::to_string(g_known));
    result->addClass(g_failed == 0 ? "pass" : "fail");
}

// A Wrapper method that throws (kui::Error) fails its group instead of aborting the tour.
void run_group(const char* group, const std::function<void()>& body) {
    try {
        body();
    } catch (const std::exception& error) {
        check(cat(group, ".exception"), false, error.what());
    }
}

void set_text(const char* id, const std::string& text) {
    if (kui::Element* element = g_doc->getElementById(id)) element->setTextContent(text);
}

kui::ExtensionManager* ext() { return g_doc->extensionManager(); }

// ---- Paths: the extension DLL and the bundled glTF model sit next to the executable --------

std::string g_exe_dir;
std::string g_ext_path;
std::string g_tank_path;

void find_paths() {
    g_exe_dir = tour_executable_dir();
    g_ext_path = g_exe_dir + "/" + k_ext_file;
    g_tank_path = g_exe_dir + "/assets/native_3d/stylized_tank.glb";
}

// ---- Extension calls: typed arguments in, a result out --------------------------------------
// invoke() throws when it could not produce a result at all; whether the call itself worked is
// the result's status (0 ok, 3 unknown method, 4 wrong argument count).

using kui::ExtensionValue;
using Args = std::vector<ExtensionValue>;

ExtensionValue v_int(long long value) { return ExtensionValue::integer(value); }
ExtensionValue v_num(double value) { return ExtensionValue::number(value); }
ExtensionValue v_str(const std::string& value) { return ExtensionValue::string(value); }

// Invokes `method` on the current #view; ok is false when there is no view or no result.
struct Call {
    bool ok = false;
    kui::ExtensionInvokeResult result;
};

Call call3d(const char* method, const Args& args, std::size_t max_results) {
    Call call;
    kui::Element* view = g_doc->getElementById("view");
    if (!view) return call;
    try {
        call.result = ext()->invoke(view, method, args, max_results);
        call.ok = true;
    } catch (const kui::Error& error) {
        std::fprintf(stderr, "kui_api_extension_3d: invoke %s: %s\n", method, error.what());
    }
    return call;
}

int status_of(const Call& call) { return call.ok ? static_cast<int>(call.result.status) : -1; }

// First result as an integer (entity / asset handle); 0 when the call failed.
long long call_int(const char* method, const Args& args) {
    const Call call = call3d(method, args, 1);
    if (status_of(call) == 0 && !call.result.values.empty() &&
        call.result.values[0].type == kui::ExtensionValueType::Integer)
        return call.result.values[0].intValue;
    return 0;
}

// true when the call succeeded and its first result (if any) is true.
bool call_ok(const char* method, const Args& args) {
    const Call call = call3d(method, args, 1);
    bool ok = status_of(call) == 0;
    if (ok && !call.result.values.empty() && call.result.values[0].type == kui::ExtensionValueType::Boolean)
        ok = call.result.values[0].boolValue;
    return ok;
}

// "status=3 count=0 error=..." or the integer values, for the result panel.
std::string describe_result(const Call& call) {
    const auto& values = call.result.values;
    std::string out = cat("status=", status_of(call), " count=", values.size());
    for (std::size_t index = 0; index < values.size(); ++index) {
        out += cat(index ? "," : " values=",
                   values[index].type == kui::ExtensionValueType::Integer ? values[index].intValue : 0LL);
    }
    if (!call.result.error.empty()) out += " error=" + call.result.error;
    return out;
}

// ---- Orbit camera: azimuth / elevation / distance around the origin -> setCameraLookAt ------

const double k_pi = 3.14159265358979323846;
double deg(double d) { return d * k_pi / 180.0; }

double g_az = 35.0;
double g_el = 22.0;
double g_dist = 8.0;

void clamp_camera() {
    if (g_el > 80.0) g_el = 80.0;
    if (g_el < -10.0) g_el = -10.0;
    if (g_dist < 3.0) g_dist = 3.0;
    if (g_dist > 30.0) g_dist = 30.0;
    while (g_az >= 360.0) g_az -= 360.0;
    while (g_az < 0.0) g_az += 360.0;
}

// Sends the camera to the extension and shows it; returns the invoke status (0 = ok).
int apply_camera() {
    clamp_camera();
    const Call call = call3d("setCameraLookAt",
                             {v_num(g_dist * std::cos(deg(g_el)) * std::sin(deg(g_az))),
                              v_num(0.3 + g_dist * std::sin(deg(g_el))),
                              v_num(g_dist * std::cos(deg(g_el)) * std::cos(deg(g_az))), v_num(0.0), v_num(0.3),
                              v_num(0.0)},
                             0);
    set_text("cam-out", "az=" + fixed(g_az, 0) + " el=" + fixed(g_el, 0) + " dist=" + fixed(g_dist, 1));
    return status_of(call);
}

void camera_step(double d_az, double d_el, double zoom) {
    g_az += d_az;
    g_el += d_el;
    g_dist *= zoom;
    apply_camera();
}

void camera_reset() {
    g_az = 35.0;
    g_el = 22.0;
    g_dist = 8.0;
    apply_camera();
}

// ---- Scene: ground, three meshes, two lights, PBR materials and the glTF tank ---------------

struct Scene {
    long long ground = 0, box = 0, sphere = 0, cylinder = 0, sun = 0, lamp = 0, tank = 0;
    bool transforms_ok = false, materials_ok = false, tank_transform_ok = false;
};

Scene g_scene;
int g_color = 0;
bool g_spinning = false;
double g_spin_angle = 0.0;
kui::u32 g_spin_timer = 0;
bool g_tank_on = true;

const double k_box_colors[4][3] = {{0.20, 0.55, 0.95}, {0.95, 0.65, 0.15}, {0.65, 0.30, 0.90}, {0.95, 0.95, 0.95}};

// setEntityTransform(entity, position, rotation quaternion about Y, uniform scale) -> bool.
bool place(long long entity, double x, double y, double z, double angle, double scale) {
    return call_ok("setEntityTransform", {v_int(entity), v_num(x), v_num(y), v_num(z), v_num(0.0),
                                          v_num(std::sin(angle * 0.5)), v_num(0.0), v_num(std::cos(angle * 0.5)),
                                          v_num(scale), v_num(scale), v_num(scale)});
}

// createBox / createSphere / ...(r, g, b) -> entity, then addToScene and place it.
long long add_mesh(const char* method, double r, double g, double b, double x, double y, double z, double scale) {
    const long long entity = call_int(method, {v_num(r), v_num(g), v_num(b)});
    if (!entity) return 0;
    if (!call_ok("addToScene", {v_int(entity)})) return 0;
    if (!place(entity, x, y, z, 0.0, scale)) g_scene.transforms_ok = false;
    return entity;
}

// setMaterialProperties(entity, r, g, b, metallic, roughness) -> bool.
bool set_material(long long entity, double r, double g, double b, double metallic, double roughness) {
    return call_ok("setMaterialProperties", {v_int(entity), v_num(r), v_num(g), v_num(b), v_num(metallic),
                                             v_num(roughness)});
}

// loadGltf(path) -> asset handle (also adds it to the scene); setAssetTransform places it.
void load_tank() {
    g_scene.tank = call_int("loadGltf", {v_str(g_tank_path)});
    g_scene.tank_transform_ok = false;
    if (!g_scene.tank) return;
    g_scene.tank_transform_ok =
        call_ok("setAssetTransform", {v_int(g_scene.tank), v_num(0.0), v_num(-0.75), v_num(-2.6), v_num(0.0),
                                      v_num(0.0), v_num(0.0), v_num(1.0), v_num(0.9), v_num(0.9), v_num(0.9)});
}

void recolor_box() {
    const double* c = k_box_colors[g_color];
    set_material(g_scene.box, c[0], c[1], c[2], 0.1, 0.45);
}

void build_scene() {
    g_scene = Scene{};
    g_scene.transforms_ok = true;
    g_spin_angle = 0.0;

    call_ok("setCameraProjection", {v_num(55.0), v_num(0.1), v_num(300.0)});
    call_ok("setSkyboxColor", {v_num(0.04), v_num(0.07), v_num(0.14)});
    // createDirectionalLight(r, g, b, intensity, dirX, dirY, dirZ)
    g_scene.sun = call_int("createDirectionalLight",
                           {v_num(1.0), v_num(0.95), v_num(0.88), v_num(110000.0), v_num(-0.8), v_num(-1.0), v_num(-0.5)});
    // createPointLight(r, g, b, intensity, x, y, z, range)
    g_scene.lamp = call_int("createPointLight", {v_num(0.35), v_num(0.6), v_num(1.0), v_num(60000.0), v_num(-2.5),
                                                 v_num(3.5), v_num(2.0), v_num(12.0)});

    g_scene.ground = add_mesh("createPlane", 0.20, 0.24, 0.30, 0.0, -0.75, 0.0, 9.0);
    g_scene.box = add_mesh("createBox", 0.2, 0.55, 0.95, 0.0, 0.0, 0.0, 1.4);
    g_scene.sphere = add_mesh("createSphere", 0.9, 0.25, 0.2, -2.4, 0.0, 0.0, 1.3);
    g_scene.cylinder = add_mesh("createCylinder", 0.25, 0.85, 0.45, 2.4, 0.0, 0.0, 1.1);

    g_scene.materials_ok = set_material(g_scene.sphere, 0.9, 0.25, 0.2, 0.9, 0.2) &&
                           set_material(g_scene.cylinder, 0.25, 0.85, 0.45, 0.0, 0.8);
    recolor_box();
    if (g_tank_on) load_tank();
    apply_camera();
}

// A fresh <kui-3d-view id="view"> in #view-host (after a reload the old one is gone).
void create_view() {
    kui::Element* host = g_doc->getElementById("view-host");
    if (!host) return;
    auto view = g_doc->createElement(k_tag);
    view->setAttribute("id", "view");
    host->appendChild(view);
}

// Removes the 3D element before its extension goes away, so the element never outlives the
// code that renders it.
void remove_view() {
    if (kui::Element* view = g_doc->getElementById("view")) view->remove();
}

// ---- Mouse orbit: listeners on #view-host (events bubble up from the 3D element) ------------
// Left drag orbits, right drag (vertical) zooms, every wheel event zooms in one step (as in the
// C port, whose ABI has no accessor for a DOM wheel event's delta).

int g_drag_button = 0;
float g_last_x = 0, g_last_y = 0;

void on_view_down(kui::MouseEvent& event) {
    g_last_x = event.clientX();
    g_last_y = event.clientY();
    g_drag_button = event.button();
}

void on_view_move(kui::MouseEvent& event) {
    if (!g_drag_button) return;
    const float x = event.clientX();
    const float y = event.clientY();
    if (g_drag_button == KUI_C_MOUSE_BUTTON_LEFT) {
        camera_step(-(x - g_last_x) * 0.5, (y - g_last_y) * 0.3, 1.0);
    } else if (g_drag_button == KUI_C_MOUSE_BUTTON_RIGHT) {
        camera_step(0.0, 0.0, 1.0 + (y - g_last_y) * 0.01);
    }
    g_last_x = x;
    g_last_y = y;
}

// ---- Camera and scene buttons ----------------------------------------------------------------

void spin_tick() {
    g_spin_angle += 0.06;
    place(g_scene.box, 0.0, 0.0, 0.0, g_spin_angle, 1.4);
    place(g_scene.cylinder, 2.4, 0.0, 0.0, -g_spin_angle, 1.1);
}

void show_scene_state() {
    set_text("scene-out", cat("color=", g_color, " spin=", g_spinning ? "on" : "off", " tank=",
                              g_scene.tank ? "on" : "off", " entities=", g_scene.ground, ",", g_scene.box, ",",
                              g_scene.sphere, ",", g_scene.cylinder));
}

void on_scene_color() {
    g_color = (g_color + 1) % 4;
    recolor_box();
    show_scene_state();
}

void stop_spin() {
    if (!g_spinning) return;
    kui::Platform::clearTimer(g_spin_timer);
    g_spinning = false;
}

void on_scene_spin() {
    if (g_spinning) {
        stop_spin();
    } else {
        g_spin_timer = kui::Platform::setInterval([] { spin_tick(); }, 33);
        g_spinning = true;
    }
    show_scene_state();
}

void on_scene_tank() {
    if (g_scene.tank) {
        call_ok("destroyAsset", {v_int(g_scene.tank)});
        g_scene.tank = 0;
        g_tank_on = false;
    } else {
        g_tank_on = true;
        load_tank();
    }
    show_scene_state();
}

// ---- Extension manager buttons ----------------------------------------------------------------

void show_ext_state(const std::string& prefix) {
    set_text("ext-out", cat(prefix, "loaded=", ext()->isExtensionLoaded(k_tag) ? 1 : 0, " extensions=", ext()->count(),
                            " watching=", ext()->isWatching() ? 1 : 0));
}

void show_perf(const std::string& prefix) {
    const kui::ExtensionManager::PerfStats stats = ext()->getPerfStats(k_tag);
    set_text("ext-out", cat(prefix, "ticks=", stats.tickCount, " paints=", stats.paintCount, " max_tick=",
                            stats.maxTickMs, "ms max_paint=", stats.maxPaintMs, "ms"));
}

void on_ext_reset() {
    ext()->resetPerfStats();
    show_perf("reset: ");
}

// Unload -> reload from the DLL path -> fresh element -> rebuilt scene.
bool reload_3d() {
    stop_spin();
    remove_view();
    ext()->unloadExtension(k_tag);
    const bool reloaded = ext()->reloadExtension(g_ext_path);
    create_view();
    build_scene();
    return reloaded;
}

void on_ext_reload() {
    const bool reloaded = reload_3d();
    show_ext_state(cat("reloaded=", reloaded ? 1 : 0, " box=", g_scene.box ? "rebuilt" : "missing", " | "));
}

void on_ext_watch() {
    if (ext()->isWatching())
        ext()->stopWatching();
    else
        ext()->startWatching(g_exe_dir);
    show_ext_state("");
}

// ---- Invoke result buttons ----------------------------------------------------------------------

void show_invoke(const char* method, std::size_t arg_count, std::size_t max_results) {
    const Args args = arg_count ? Args{v_int(0)} : Args{};
    const Call call = call3d(method, args, max_results);
    set_text("res-out", call.ok ? describe_result(call) : std::string("no result (no 3D view)"));
}

// ---- Self-check: the scene built through extension calls -------------------------------------

void check_scene(const std::string& prefix) {
    check(prefix + ".lights", g_scene.sun != 0 && g_scene.lamp != 0,
          cat("sun ", g_scene.sun, ", point light ", g_scene.lamp));
    check(prefix + ".meshes", g_scene.ground && g_scene.box && g_scene.sphere && g_scene.cylinder &&
          g_scene.box != g_scene.sphere && g_scene.sphere != g_scene.cylinder && g_scene.ground != g_scene.box,
          cat("entities ", g_scene.ground, " ", g_scene.box, " ", g_scene.sphere, " ", g_scene.cylinder));
    check(prefix + ".transforms", g_scene.transforms_ok, "setEntityTransform returned false");
    check(prefix + ".materials", g_scene.materials_ok, "setMaterialProperties returned false");
    check(prefix + ".gltf", g_scene.tank != 0 && g_scene.tank_transform_ok,
          cat("loadGltf(", g_tank_path, ") -> ", g_scene.tank, ", setAssetTransform ", g_scene.tank_transform_ok));
}

// ---- Self-check: invoke results (status, count, values, error) --------------------------------

void check_results() {
    {
        const Call call = call3d("getRenderStats", {}, 4);
        bool all_int = true;
        for (const auto& value : call.result.values)
            all_int = all_int && value.type == kui::ExtensionValueType::Integer;
        check("res.get_count", status_of(call) == 0 && call.result.values.size() == 4 && all_int,
              cat("getRenderStats: status ", status_of(call), " count ", call.result.values.size()));
        check("res.get_error-empty", call.ok && call.result.error.empty(),
              cat("error on success '", call.result.error, "'"));
    }
    {
        const Call call = call3d("noSuchMethod", {}, 1);
        check("res.status-unknown-method",
              status_of(call) == static_cast<int>(kui::ExtensionInvokeStatus::MethodNotFound) &&
                  call.result.values.empty() && call.result.error.find("noSuchMethod") != std::string::npos,
              cat("status ", status_of(call), " count ", call.result.values.size(), " error '", call.result.error, "'"));
    }
    {
        const Call call = call3d("addToScene", {}, 1);
        check("res.status-arg-count",
              status_of(call) == static_cast<int>(kui::ExtensionInvokeStatus::InvalidArgumentCount) &&
                  !call.result.error.empty(),
              cat("status ", status_of(call), " error '", call.result.error, "'"));
    }
}

// ---- Self-check: the orbit camera, through the buttons' function and real mouse events -------

bool approx(double a, double b) { return a - b < 0.01 && b - a < 0.01; }

void mouse(KuiCMouseEventType type, float x, float y, KuiCMouseButton button, int clicks, float wheel_y) {
    g_doc->dispatchMouse(type, x, y, button, 0, clicks, 0.0f, wheel_y);
}

void check_camera() {
    check("cam.set_camera_look_at", apply_camera() == 0, "setCameraLookAt failed");
    camera_step(15.0, 0.0, 1.0);
    check("cam.step", approx(g_az, 50.0), cat("azimuth ", g_az, " after +15"));

    kui::Element* host = g_doc->getElementById("view-host");
    const kui::Rect rect = host ? host->boundingClientRect() : kui::Rect{};
    const float cx = rect.x + rect.width * 0.5f;
    const float cy = rect.y + rect.height * 0.5f;

    // Left drag 40 px to the right: the mousedown / mousemove / mouseup listeners turn it into
    // -20 degrees of azimuth.
    double before = g_az;
    mouse(KUI_C_MOUSE_PRESSED, cx, cy, KUI_C_MOUSE_BUTTON_LEFT, 1, 0.0f);
    mouse(KUI_C_MOUSE_MOVED, cx + 40.0f, cy, KUI_C_MOUSE_BUTTON_LEFT, 0, 0.0f);
    mouse(KUI_C_MOUSE_RELEASED, cx + 40.0f, cy, KUI_C_MOUSE_BUTTON_LEFT, 1, 0.0f);
    check("cam.mouse-drag-orbit", approx(g_az, before - 20.0) && g_drag_button == 0,
          cat("azimuth ", before, " -> ", g_az, ", drag button ", g_drag_button));

    // Right drag 20 px down zooms out by 20 %.
    before = g_dist;
    mouse(KUI_C_MOUSE_PRESSED, cx, cy, KUI_C_MOUSE_BUTTON_RIGHT, 1, 0.0f);
    mouse(KUI_C_MOUSE_MOVED, cx, cy + 20.0f, KUI_C_MOUSE_BUTTON_RIGHT, 0, 0.0f);
    mouse(KUI_C_MOUSE_RELEASED, cx, cy + 20.0f, KUI_C_MOUSE_BUTTON_RIGHT, 1, 0.0f);
    check("cam.mouse-drag-zoom", approx(g_dist, before * 1.2), cat("distance ", before, " -> ", g_dist));

    before = g_dist;
    mouse(KUI_C_MOUSE_WHEEL, cx, cy, KUI_C_MOUSE_BUTTON_NONE, 0, -120.0f);
    check("cam.mouse-wheel", approx(g_dist, before * 0.9), cat("distance ", before, " -> ", g_dist));
    camera_reset();
}

// ---- Self-check: extension manager state, perf stats and directory watching -------------------

std::size_t g_initial_count = 0;

int ext_loaded() { return ext()->isExtensionLoaded(k_tag) ? 1 : 0; }

void check_manager() {
    check("ext.is_loaded", ext_loaded() == 1, cat("kui-3d-view loaded=", ext_loaded()));
    g_initial_count = ext()->count();
    bool watching = ext()->isWatching();
    check("ext.get_extension_state", g_initial_count >= 1 && !watching,
          cat("count ", g_initial_count, " watching ", watching));

    ext()->startWatching(g_exe_dir);
    watching = ext()->isWatching();
    check("ext.watch_extensions-on", watching, cat("watching ", watching));
    ext()->stopWatching();
    watching = ext()->isWatching();
    check("ext.watch_extensions-off", !watching, cat("watching ", watching));

    std::string error;
    kui::ExtensionManager::PerfStats stats;
    stats.tickCount = static_cast<kui::u64>(-1);
    try {
        stats = ext()->getPerfStats(k_tag);
    } catch (const kui::Error& thrown) {
        error = thrown.what();
    }
    check("perf.get_perf_stats", error.empty() && stats.tickCount != static_cast<kui::u64>(-1), cat("error '", error, "'"));
}

// Unload -> confirm -> reload -> load, before the page has any 3D element: the element is created
// afterwards, on the extension that is loaded at the end. (The "Unload + reload 3D" button does
// the same with a live view; the example's pixel check covers that second view.)
void check_lifecycle() {
    bool unloaded = ext()->unloadExtension(k_tag);
    check("ext.unload_extension", unloaded && ext_loaded() == 0 && ext()->count() == g_initial_count - 1,
          cat("unloaded ", unloaded, " loaded ", ext_loaded(), " count ", ext()->count()));
    unloaded = ext()->unloadExtension(k_tag);  // false: KUI_ERR_NOT_FOUND
    check("ext.unload_extension-again", !unloaded, cat("unloaded ", unloaded));

    const bool reloaded = ext()->reloadExtension(g_ext_path);
    check("ext.reload_extension", reloaded && ext_loaded() == 1 && ext()->count() == g_initial_count,
          cat("reloaded ", reloaded, " loaded ", ext_loaded(), " count ", ext()->count()));

    const std::string missing = g_exe_dir + "/no_such_extension_" + k_ext_file;
    bool loaded = ext()->loadExtension(missing);
    check("ext.load_extension-missing", !loaded && ext()->count() == g_initial_count,
          cat("loaded ", loaded, " count ", ext()->count()));

    // unloadAll removes the custom element definitions of every extension it unloads (like
    // unloadExtension does), so the DLLs can be loaded again below.
    ext()->unloadAll();
    check("ext.unload_all_extensions", ext()->count() == 0 && ext_loaded() == 0,
          cat("count ", ext()->count(), " loaded ", ext_loaded()));
    const bool defined = g_doc->customElements()->isDefined("kui-editor");
    check("ext.unload_all-undefines-elements", !defined,
          cat("<kui-editor> still defined=", defined ? 1 : 0));

    loaded = ext()->loadExtension(g_ext_path);
    check("ext.load_extension", loaded && ext()->count() == 1 && ext_loaded() == 1,
          cat("loaded ", loaded, " count ", ext()->count()));
}

// After a few frames: what the perf counters saw, then reset them; publish the verdict.
void check_perf_and_finish() {
    kui::ExtensionManager::PerfStats stats = ext()->getPerfStats(k_tag);
    known("perf.paints-recorded", stats.paintCount > 0 || stats.tickCount > 0,
          "ExtensionManager never records tick / paint timings (recordTickPerf / recordPaintPerf "
          "have no caller)",
          cat("ticks ", stats.tickCount, " paints ", stats.paintCount, " after rendering"));
    ext()->resetPerfStats();
    stats = ext()->getPerfStats(k_tag);
    check("perf.reset_perf_stats", stats.tickCount == 0 && stats.paintCount == 0 && stats.totalPaintMs == 0.0,
          cat("ticks ", stats.tickCount, " paints ", stats.paintCount));
    show_ext_state("self-check done | ");
    finish();
}

// Clicks on #id run `handler` (a missing button is reported as a failed check).
void on_click(const char* id, void (*handler)()) {
    kui::Element* button = g_doc->getElementById(id);
    if (!button) {
        check(cat("ui.", id), false, "button missing");
        return;
    }
    button->addEventListener("click", [handler, id](kui::Event&) {
        try {
            handler();
        } catch (const std::exception& error) {
            std::fprintf(stderr, "kui_api_extension_3d: #%s: %s\n", id, error.what());
        }
    });
}

}  // namespace

void tour_ready(kui::Window& window, kui::Document& document) {
    (void)window;
    g_doc = &document;
    find_paths();

    if (kui::Element* host = g_doc->getElementById("view-host")) {
        host->addEventListener("mousedown", [](kui::MouseEvent& event) { on_view_down(event); });
        host->addEventListener("mousemove", [](kui::MouseEvent& event) { on_view_move(event); });
        host->addEventListener("mouseup", [](kui::Event&) { g_drag_button = 0; });
        host->addEventListener("mouseleave", [](kui::Event&) { g_drag_button = 0; });
        host->addEventListener("wheel", [](kui::Event&) { camera_step(0.0, 0.0, 0.9); });
    }

    run_group("ext", check_manager);
    run_group("lifecycle", check_lifecycle);
    run_group("scene", [] {
        create_view();
        build_scene();
        check_scene("scene");
    });
    run_group("res", check_results);
    run_group("cam", check_camera);
    show_scene_state();
    kui::Platform::setTimeout([] {
        run_group("perf", check_perf_and_finish);
    }, 400);

    on_click("btn-cam-left", [] { camera_step(-15.0, 0.0, 1.0); });
    on_click("btn-cam-right", [] { camera_step(15.0, 0.0, 1.0); });
    on_click("btn-cam-up", [] { camera_step(0.0, 10.0, 1.0); });
    on_click("btn-cam-down", [] { camera_step(0.0, -10.0, 1.0); });
    on_click("btn-cam-in", [] { camera_step(0.0, 0.0, 0.8); });
    on_click("btn-cam-out", [] { camera_step(0.0, 0.0, 1.25); });
    on_click("btn-cam-reset", camera_reset);
    on_click("btn-scene-color", on_scene_color);
    on_click("btn-scene-spin", on_scene_spin);
    on_click("btn-scene-tank", on_scene_tank);
    on_click("btn-ext-state", [] { show_ext_state(""); });
    on_click("btn-ext-perf", [] { show_perf(""); });
    on_click("btn-ext-reset", on_ext_reset);
    on_click("btn-ext-reload", on_ext_reload);
    on_click("btn-ext-watch", on_ext_watch);
    on_click("btn-res-ok", [] { show_invoke("getRenderStats", 0, 4); });
    on_click("btn-res-unknown", [] { show_invoke("noSuchMethod", 0, 1); });
    on_click("btn-res-args", [] { show_invoke("addToScene", 0, 1); });
}
// ---- end of examples/api_tours/extension_3d/host.cpp ----

int main() {
    try {
        if (!kui::Platform::init()) return 3;
        kui::WindowConfig config;
        config.title = "KUI API \xe2\x80\x94 extensions & host-driven 3D";
        config.width = 1100;
        config.height = 780;
        auto window = kui::Window::create(config);
        if (!window) return 4;
        kui::Document* document = window->document();
        auto script = kui::ScriptEngine::create();
        if (script) {
            script->setErrorHandler([](const std::string& error, const std::string& source, int line) {
                std::fprintf(stderr, "[Lua] %s:%d: %s\n", source.c_str(), line, error.c_str());
            });
            script->bindDocument(document);
            window->setScriptEngine(script.get());
        }
        tour_script = script.get();
        document->initExtensions(tour_executable_dir());
        document->loadHTML(k_tour_page);
        if (script) script->executeScripts();
        // Test hook shared with the C / Go / Rust runners: KUI_EXAMPLE_DEVTOOLS_PORT=<port> starts
        // DevTools so scripts/verify_example_ports.py can click and read the DOM.
        const std::string port = tour_env("KUI_EXAMPLE_DEVTOOLS_PORT");
        if (!port.empty()) window->startDevTools(static_cast<kui::u16>(std::atoi(port.c_str())));
        tour_ready(*window, *document);
        const int code = kui::Platform::run();
        tour_script = nullptr;
        return code;
    } catch (const std::exception& error) {
        std::fprintf(stderr, "[kui_api_extension_3d] %s\n", error.what());
        return 9;
    }
}
